parameters.cypher_query:
MATCH (p:Person)-[r:ATTACKER_COMMANDER|DEFENDER_COMMANDER|ATTACKER_KING|DEFENDER_KING]->(b:Battle)
RETURN gds.graph.project(
  $graph_name, p, b,
  {
    sourceNodeLabels: labels(p),
    targetNodeLabels: labels(b),
    relationshipType: type(r)
  },
  {undirectedRelationshipTypes: ['ATTACKER_COMMANDER','DEFENDER_COMMANDER','ATTACKER_KING','DEFENDER_KING']}
)

