parameters.cypher_query:
MATCH (n) WHERE n:Battle OR n:Person
OPTIONAL MATCH (n)-[r:ATTACKER_COMMANDER|DEFENDER_COMMANDER]->(m)
WHERE m:Battle OR m:Person
RETURN gds.graph.project(
  $graph_name, n, m,
  {
    sourceNodeLabels: labels(n),
    targetNodeLabels: labels(m),
    relationshipType: type(r)
  },
  {undirectedRelationshipTypes: ['ATTACKER_COMMANDER','DEFENDER_COMMANDER']}
)

